using System.Threading.Tasks;

using Microsoft.CodeAnalysis.Diagnostics;

using Xunit;

namespace DiagnosticCatalog.Analyzers.UnitTests;

/// <summary>
/// What each analyzer does with a tree Roslyn considers generated.
/// </summary>
/// <remarks>
/// The two analyzers exist as two classes for this reason alone: a generated catalogue is the main
/// thing the definition diagnostics have to check, and a generated file is the last place a use-site
/// suppression should be rewritten. Nothing observed either half of that until these tests, and the
/// definition half was not delivering it — <c>GeneratedCodeAnalysisFlags.Analyze</c> runs the
/// callbacks and then discards every diagnostic they report, which reads exactly like a rule that
/// found nothing.
///
/// Roslyn decides a tree is generated from its file path or from an <c>&lt;auto-generated&gt;</c>
/// banner. The harness parses without a path, so the banner is what these fixtures carry — the same
/// one <c>DcatRules.g.cs</c> opens with.
/// </remarks>
public sealed class GeneratedCodeTests
{
    private static readonly DiagnosticAnalyzer DefinitionAnalyzer = new DiagnosticRuleDefinitionAnalyzer();

    private static readonly DiagnosticAnalyzer UsageAnalyzer = new SuppressionUsageAnalyzer();

    // First thing in the file, and it has to be: Roslyn only reads the banner when it precedes every
    // other token.
    private const string GeneratedBanner = """
        // <auto-generated>
        //     Generated by a fixture. Do not edit by hand.
        // </auto-generated>

        """;

    private const string UsingFoundation = "using DiagnosticCatalog;\n";

    private const string CategoryContainer = """
        [DiagnosticCategory]
        internal static class Cat
        {
            public const string Usage = "Usage";
        }

        """;

    // A rule type that is not static: DCAT0002, reached through the symbol action.
    private const string RuleFailingTheStructuralContract = """
        [DiagnosticRule]
        public class JD0002
        {
            public const string Id = nameof(JD0002);
            public const string Category = Cat.Usage;
        }
        """;

    // A category written as a literal: DCAT0011, reached through the syntax action. Both registration
    // kinds are covered, because the flag filters reported diagnostics rather than callbacks and a
    // difference between the two would be invisible from either one alone.
    private const string RuleWithAnUnreferencedCategory = """
        [DiagnosticRule]
        public static class JD0011
        {
            public const string Id = nameof(JD0011);
            public const string Category = "Usage";
        }
        """;

    [Fact]
    public Task A_structural_defect_in_ordinary_source_is_reported() =>
        AnalyzerHarness.ReportsAsync(
            DefinitionAnalyzer,
            UsingFoundation + CategoryContainer + RuleFailingTheStructuralContract,
            "DCAT0002");

    [Fact]
    public Task A_structural_defect_in_generated_source_is_reported() =>
        // The control above and this one differ by the banner alone. Generated catalogues are what the
        // definition diagnostics are for; a rule they report on a hand-written file and pass over on a
        // generated one would leave every shipped catalogue unchecked.
        AnalyzerHarness.ReportsAsync(
            DefinitionAnalyzer,
            GeneratedBanner + UsingFoundation + CategoryContainer + RuleFailingTheStructuralContract,
            "DCAT0002");

    [Fact]
    public Task An_unreferenced_category_in_ordinary_source_is_reported() =>
        AnalyzerHarness.ReportsAsync(
            DefinitionAnalyzer,
            UsingFoundation + CategoryContainer + RuleWithAnUnreferencedCategory,
            "DCAT0011");

    [Fact]
    public Task An_unreferenced_category_in_generated_source_is_reported() =>
        AnalyzerHarness.ReportsAsync(
            DefinitionAnalyzer,
            GeneratedBanner + UsingFoundation + CategoryContainer + RuleWithAnUnreferencedCategory,
            "DCAT0011");

    [Fact]
    public Task A_replaceable_literal_suppression_in_ordinary_source_is_reported() =>
        AnalyzerHarness.ReportsAsync(
            UsageAnalyzer,
            UsingFoundation + CategoryContainer + LiteralSuppression,
            "DCAT0006");

    [Fact]
    public Task A_replaceable_literal_suppression_in_generated_source_stays_silent() =>
        // The other half of the split, asserted so the two flags cannot be brought into line by
        // mistake. A generator emits the suppressions its template holds; telling its author to
        // migrate a file they do not edit is noise, and the fix would be overwritten on the next run.
        AnalyzerHarness.ReportsNothingAsync(
            UsageAnalyzer,
            GeneratedBanner + UsingFoundation + CategoryContainer + LiteralSuppression);

    private const string LiteralSuppression = """
        [DiagnosticRule]
        public static class JD0006
        {
            public const string Id = nameof(JD0006);
            public const string Category = Cat.Usage;
        }

        internal static class Consumer
        {
            [System.Diagnostics.CodeAnalysis.SuppressMessage("Usage", "JD0006", Justification = "j")]
            public static void Method() { }
        }
        """;
}
